/**
 * @param {number} n
 * @param {number[][]} reservedSeats
 * @return {number}
 */
var maxNumberOfFamilies = function(n, reservedSeats) {
    const matrix = Array.from({ length: n }, () => Array(10).fill(false));

    for (const [row, seat] of reservedSeats) {
        matrix[row - 1][seat - 1] = true;
    }

    let res = 0;

    for (let row = 0; row < n; row++) {
        for (let col = 1; col <= 5; col += 2) {
            if (!matrix[row][col] &&
                !matrix[row][col + 1] &&
                !matrix[row][col + 2] &&
                !matrix[row][col + 3]) {
                res++;
                col += 2;
            }
        }
    }

    return res;
};

/**
 * @param {number} n
 * @param {number[][]} reservedSeats
 * @return {number}
 */
var maxNumberOfFamilies = function(n, reservedSeats) {
    const map = new Map();

    for (const [row, seat] of reservedSeats) {
        const set = map.get(row) || new Set();
        if (set.size === 0) map.set(row, set);
        set.add(seat);
    }

    let res = n * 2;

    for (const [row, set] of map) {
        const start = !set.has(2) && !set.has(3);
        const mid1 = !set.has(4) && !set.has(5);
        const mid2 = !set.has(6) && !set.has(7);
        const end = !set.has(8) && !set.has(9);

        const free0 = start && mid1;
        const free2 = mid2 && end;

        if (!free0 || !free2) {
            const free1 = mid1 && mid2;

            if (free0 || free1 || free2) {
                res--;
            } else {
                res -= 2;
            }
        }
    }

    return res;
};
